function tensorform(P::MG)

    I, S, A, R, T = P.I, P.S, P.A, P.R, P.T

    I' = eachindex(I)

    S' = eachindex(S)

    A' = [eachindex(A[i]) for i in I]

    R' = [R(s,a) for s in S, a in joint(A)]

    T' = [T(s,a,s') for s in S, a in joint(A), s' in S]

    return I', S', A', R', T'

